/* ============================================================
   أطياب الجاسم (React) — تفاصيل المنتج (ProductDetails)

   يأخذ props = معرّف المنتج (id) ويجلب بياناته بنفسه من Redux/البيانات،
   ويعرض: صورة كبيرة على اليمين مع تنقّل بين الصور (يمين/يسار) + شارة
   العرض أعلى الصورة بخط صغير، وعلى اليسار: زرّا المفضلة والمشاركة،
   العنوان، الحجم، مناسب لمن (أو نوع البخور)، الشرح، «اعرف قصته» في
   شاشة منبثقة، التقييم وعدد المشتريات، السعر والسعر قبل الخصم ونسبة
   التوفير، شريط القطع المتبقية، و(+/-) للكمية، والمزايا، ثم زر الإضافة
   إلى العربة (ProductButtons) الذي يضيف إلى العربة من Redux.

   ★ من يرسل الـid؟ بطاقة المنتج عند الضغط عليها، وزر «تفاصيل المنتج»
     في ProductButtons — كلاهما يمرّر id.
   ============================================================ */

import { useCallback, useEffect, useMemo, useState } from "react";
import { Link } from "react-router-dom";
import { PATHS, pathOf } from "../../routes.js";
import { ATYAB_catalogOf, ATYAB_byId } from "../../data/products.js";
import { productName, productDesc, productSize, productKind, nounOf, countOfNoun, genderLabelOf, tr2 } from "../../i18n.js";
import { useAppDispatch, useAppSelector } from "../../redux/hooks.js";
import { uiActions } from "../../redux/slices/uiSlice.js";
import { unitPriceOf } from "../../redux/selectors.js";
import { Money, Stars } from "../Source/Money.jsx";
import { Icon, ProductImage } from "../Source/Icons.jsx";
import { AddToCartButton } from "../Buttons/ProductButtons.jsx";
import { selectProductProfile, selectProfileLoading } from "../../redux/slices/productProfilesSlice.js";
import { selectProductGallery } from "../../redux/slices/imagesSlice.js";
import AddToFavoritesButton from "../Buttons/AddToFavoritesButton.jsx";
import ShareProductButton from "../Buttons/ShareProductButton.jsx";
import { StorySkeleton } from "../Skeletons/index.js";
import "../Skeletons/Skeletons.css";

/* ★ المعرض = الصورة الأساسية + صور الـ API (زوايا المنتج الأربع) — صور حقيقية فقط، بلا عناوين ولا توضيحي */
function slotsFor(p, lang, gallery) {
  const seen = {};
  const photos = [p.image].concat(gallery || []).filter(function (u) {
    if (!u || seen[u]) return false;
    seen[u] = 1;
    return true;
  });
  return photos.map(function (src, i) {
    return { src: src, title: (lang === "en" ? "Photo " : "صورة ") + (i + 1), isPhoto: true };
  });
}

function stockInfo(stock, noun, lang) {
  const n = noun || (lang === "en" ? "item" : "العطر");
  if (stock <= 0) {
    return {
      cls: "is-out",
      text: tr2(lang, "Currently out of stock", "نفدت الكمية حالياً"),
      hint: tr2(lang, "Add your name to the waiting list", "أضف اسمك لقائمة الانتظار")
    };
  }
  if (stock <= 5) {
    return {
      cls: "is-low",
      text: tr2(lang, "Only " + stock + " left", "باقي " + stock + " قطع فقط"),
      hint: tr2(lang, "Limited quantity — order before it sells out", "الكمية محدودة — اطلبه قبل النفاد")
    };
  }
  if (stock <= 12) {
    return {
      cls: "is-mid",
      text: tr2(lang, stock + " left", "باقي " + stock + " قطعة"),
      hint: tr2(lang, "Demand is high for this " + n, "الطلب مرتفع على هذا " + n)
    };
  }
  return {
    cls: "is-ok",
    text: tr2(lang, "In stock — " + stock + " left", "متوفر — باقي " + stock + " قطعة"),
    hint: tr2(lang, "Ready to ship today", "جاهز للشحن اليوم")
  };
}

export default function ProductDetails(props) {
  const dispatch = useAppDispatch();
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });
  const id = Number(props.id);
  const stored = props.product || (ATYAB_byId ? ATYAB_byId(id) : null);
  const product = stored;
  /* ★ البروفايل (قصة/وصف/نوتات) والمعرض — يُجلبان عند فتح البطاقة فقط */
  const profile = useAppSelector(function (s) { return selectProductProfile(s, id); });
  const profileLoading = useAppSelector(function (s) { return selectProfileLoading(s, id); });
  const gallery = useAppSelector(function (s) { return selectProductGallery(s, id); });


  const [slot, setSlot] = useState(0);
  const [qty, setQty] = useState(1);

  useEffect(
    function () {
      setSlot(0);
      setQty(1);
    },
    [id]
  );

  const slots = useMemo(
    function () {
      return product ? slotsFor(product, language, gallery) : [];
    },
    [product, language, gallery]
  );

  /* ★ R17 (تجريبي): تدوير تلقائي كل ثانيتين في الهاتف — يُصفَّر المؤقّت
     مع كل تنقّل يدوي، ويتوقف تمامًا مع إعداد «تقليل الحركة» */
  const [tick, setTick] = useState(0);
  useEffect(
    function () {
      if (slots.length < 2) return undefined;
      try {
        if (window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches) return undefined;
      } catch (e) {}
      const t = window.setInterval(function () {
        setSlot(function (prev) {
          return (prev + 1) % slots.length;
        });
      }, 2000);
      return function () {
        window.clearInterval(t);
      };
    },
    [slots.length, id, tick]
  );

  const step = useCallback(
    function (delta) {
      if (!slots.length) return;
      setSlot(function (prev) {
        return ((prev + delta) % slots.length + slots.length) % slots.length;
      });
      setTick(function (t) {
        return t + 1;
      });
    },
    [slots.length]
  );

  /* لوحة المفاتيح: الأسهم تتنقّل بين الصور */
  useEffect(
    function () {
      function onKey(e) {
        if (e.target && /INPUT|TEXTAREA|SELECT/.test(e.target.tagName)) return;
        if (e.key === "ArrowLeft") step(1);
        else if (e.key === "ArrowRight") step(-1);
      }
      window.addEventListener("keydown", onKey);
      return function () {
        window.removeEventListener("keydown", onKey);
      };
    },
    [step]
  );

  if (!product) {
    return (
      <>
        <div className="pd-top">
          <Link className="pd-back" to={PATHS.perfumes}>
            <Icon name="back" strokeWidth={2} />
            <span>{tr2(language, "Back to browsing products", "عد لتصفح المنتجات")}</span>
          </Link>
        </div>
        <p className="grid-empty">
          {tr2(language, "We could not find this product.", "لم نجد هذا المنتج.")}{" "}
          <Link to={PATHS.perfumes} className="gold-text">
            {tr2(language, "Browse all products", "تصفّح كل المنتجات")}
          </Link>
        </p>
      </>
    );
  }

  const cat = ATYAB_catalogOf ? ATYAB_catalogOf(product.id) : null;
  const isBakhoor = !!product.kindLabel;
  const noun = nounOf(product, language);
  const name = productName(product, language);
  const desc = productDesc(product, language);
  const fullDesc = profile ? (language === "en" ? (profile.descEn || desc) : (profile.desc || desc)) : desc;

  const now = unitPriceOf(product);
  const old = product.oldPrice || now;
  const saved = Math.max(0, old - now);
  const pct = old ? Math.round((saved / old) * 100) : 0;
  const stock = typeof product.stock === "number" ? product.stock : 10;
  const max = Math.max(1, Math.min(stock, 10));
  const info = stockInfo(stock, isBakhoor ? tr2(language, "bakhoor", "البخور") : tr2(language, "perfume", "العطر"), language);
  const stockPct = Math.max(8, Math.min(100, Math.round((stock / 30) * 100)));
  const badgeLabel = isBakhoor ? productKind(product, language) : productKind(product, language) || genderLabelOf(product.gender, language);
  const badgeIcon = isBakhoor
    ? product.kind === "oud"
      ? "oud"
      : product.kind === "tablets"
      ? "tablet"
      : product.kind === "gift"
      ? "gift"
      : product.kind === "mabkhara"
      ? "burner"
      : "flame"
    : product.gender === "men"
    ? "men"
    : product.gender === "women"
    ? "women"
    : "unisex";

  const current = slots[slot] || slots[0];

  function changeQty(delta) {
    const next = Math.min(max, Math.max(1, qty + delta));
    if (next === qty && delta > 0) {
      dispatch(uiActions.toastShown(tr2(language, "Maximum available quantity: " + max, "أقصى كمية متاحة: " + max)));
    }
    setQty(next);
  }

  return (
    <>
      <div className="pd-top">
        <Link
          className="pd-back"
          to={pathOf((cat && cat.route) || PATHS.perfumes)}
        >
          <Icon name="back" strokeWidth={2} />
          <span>{tr2(language, "Back to browsing products", "عد لتصفح المنتجات")}</span>
        </Link>
        <span className="pd-crumb">
          {tr2(language, (cat && cat.collectionFallbackEn) || "Our perfumes", (cat && cat.collectionFallback) || "عطورنا")} / <b>{name}</b>
        </span>
      </div>

      <div className="pd-main">
        {/* ===== عمود الصور ===== */}
        <div className="pd-gallery">
          <div className="pd-stage">
            <div className="pd-shot">
              {current && current.src ? (
                <ProductImage key={slot} product={product} src={current.src} alt={name + " — " + current.title} className="pd-photo" eager />
              ) : (
                <div className="img-skeleton pd-photo" aria-hidden="true" />
              )}
            </div>

            {product.offer ? <span className="card-offer">{product.offer}</span> : null}
            {/* ★ R17: أيقونتا المفضلة والمشاركة فوق الصورة (هاتف فقط) بدل الزرّين العريضين */}
            <div className="pd-stage-tools">
              <AddToFavoritesButton id={product.id} name={name} variant="mini" />
              <ShareProductButton id={product.id} variant="mini" />
            </div>
            <span className="pd-count">
              <b>{slot + 1}</b> / {slots.length}
            </span>

            <button className="pd-nav pd-nav-prev" type="button" aria-label="الصورة السابقة" onClick={function () { step(-1); }}>
              <Icon name="chevRight" strokeWidth={2.1} />
            </button>
            <button className="pd-nav pd-nav-next" type="button" aria-label="الصورة التالية" onClick={function () { step(1); }}>
              <Icon name="chevLeft" strokeWidth={2.1} />
            </button>
          </div>

          <div className="pd-thumbs" role="tablist" aria-label={tr2(language, "Photos of the " + noun, "صور " + noun)}>
            {slots.map(function (s, i) {
              return (
                <button
                  key={i}
                  className={"pd-thumb" + (i === slot ? " is-on" : "")}
                  type="button"
                  role="tab"
                  aria-selected={i === slot}
                  title={s.title}
                  onClick={function () {
                    setSlot(i);
                    setTick(function (t) {
                      return t + 1;
                    });
                  }}
                >
                  <span className="pd-thumb-art">
                    {s.src ? (
                      <img src={s.src} alt={s.title} loading="lazy" decoding="async" />
                    ) : (
                      <span className="img-skeleton" aria-hidden="true" />
                    )}
                  </span>
                  <span className="pd-thumb-cap">{s.title}</span>
                </button>
              );
            })}
          </div>

        </div>

        {/* ===== عمود المعلومات ===== */}
        <div className="pd-info">
          <div className="pd-tools">
            <AddToFavoritesButton id={product.id} name={name} variant="tool" />
            <ShareProductButton id={product.id} variant="tool" />
          </div>

          <h1 className="pd-name">{name}</h1>

          <div className="pd-tags">
            <span className={"pd-gender" + (isBakhoor ? " pd-kind" : "")}>
              <i aria-hidden="true">
                <Icon name={badgeIcon} />
              </i>
              {badgeLabel}
            </span>
            <span className="pd-size">{productSize(product, language)}</span>
          </div>

          <p className="pd-desc">{product ? fullDesc : desc}</p>
          {profileLoading && !profile ? (
            <StorySkeleton />
          ) : null}
          <button
            className="pd-more"
            type="button"
            onClick={function () {
              dispatch(uiActions.openStory(product.id));
            }}
          >
            <Icon name="spark" strokeWidth={1.6} />
            <span>اعرف قصته</span>
          </button>

          <div className="pd-rating">
            <Stars rating={product.rating} />
            <b>{product.rating}</b>
            <span className="pd-reviews">
              <button className="pd-reviews-link" type="button" onClick={function () {
                const el = document.getElementById("productRate");
                if (el) {
                  try {
                    el.scrollIntoView({ behavior: "smooth", block: "start" });
                  } catch (e) {
                    el.scrollIntoView();
                  }
                }
              }}>
                {countOfNoun(product.reviews, tr2(language, "review", "تقييماً"), language)}
              </button>
            </span>
            <span className="pd-sales">· {countOfNoun(product.sales, tr2(language, "purchase", "عملية شراء"), language)}</span>
          </div>

          <div className="pd-deal">
            <div className="pd-prices">
              <span className="pd-price-now">
                <Money sar={now} />
              </span>
              {/* ★ R18: بلا عرض = بلا سعر مشطوب (كان يعرض نفس السعر مشطوبًا) */}
              {old > now ? (
              <span className="pd-price-old">
                <Money sar={old} />
              </span>
              ) : null}
            </div>
            {saved > 0 ? (
              <span className="pd-save">
                <Icon name="spark" strokeWidth={1.6} />
                <b>
                  توفير <Money sar={saved} />
                </b>
                <em>({pct}%)</em>
              </span>
            ) : null}
          </div>

          <div className={"pd-stock " + info.cls}>
            <div className="pd-stock-top">
              <span className="pd-stock-text">{info.text}</span>
              <span className="pd-stock-hint">{info.hint}</span>
            </div>
            <span className="pd-stock-bar">
              <i style={{ width: stockPct + "%" }} />
            </span>
          </div>

          <div className="pd-buy">
            <div className="pd-qty" role="group" aria-label="الكمية">
              <button type="button" aria-label="تقليل الكمية" disabled={qty <= 1} onClick={function () { changeQty(-1); }}>
                −
              </button>
              <input id="pdQty" type="text" inputMode="numeric" value={qty} readOnly aria-label="الكمية المطلوبة" />
              <button type="button" aria-label="زيادة الكمية" disabled={qty >= max} onClick={function () { changeQty(1); }}>
                +
              </button>
            </div>
            <AddToCartButton id={product.id} qty={qty} className="btn-cart pd-add" />
          </div>

          <p className="pd-total">
            الإجمالي: <b><Money sar={now * qty} /></b>{" "}
            {old > now ? (
              <s>
                <Money sar={old * qty} />
              </s>
            ) : null}
          </p>

          <ul className="pd-perks">
            <li>
              توصيل مجاني للطلبات فوق <Money sar={300} />
            </li>
            <li>منتج أصلي 100% مع ضمان الاستبدال</li>
            <li>عيّنات مجانية مع كل طلب</li>
          </ul>
        </div>
      </div>
    </>
  );
}
