/* ============================================================
   أطياب الجاسم (React) — زرّ مشاركة المنتج (Share Product)

   يشارك رابط المنتج عبر مشاركة النظام (navigator.share) على الجوال،
   وإلا ينسخ الرابط إلى الحافظة مع تنبيه — كما في النسخة القديمة.

   ★ الرابط مبنيّ من مسار الراوتر: #/product/<id> — ويعمل عند فتحه من
     أي جهاز (رابط إطار التخزين الداخلي لا يُفتح).
   ============================================================ */

import { useCallback } from "react";
import { productPath } from "../../routes.js";
import { useAppDispatch, useAppSelector } from "../../redux/hooks.js";
import { uiActions } from "../../redux/slices/uiSlice.js";
import { ATYAB_byId } from "../../data/products.js";
import { makeMoney } from "../../redux/selectors.js";
import { Icon } from "../Source/Icons.jsx";

function shareUrlOf(id) {
  const hash = "#" + productPath(id);
  const name = (typeof window !== "undefined" && window.generatorName) || "";
  if (name) return "https://perchance.org/" + name + hash;
  if (typeof window !== "undefined" && window.location) {
    return window.location.origin + window.location.pathname + hash;
  }
  return hash;
}

export default function ShareProductButton(props) {
  const dispatch = useAppDispatch();
  const id = Number(props.id);
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });
  const currency = useAppSelector(function (s) {
    return s.user.profile.currency;
  });

  const onShare = useCallback(
    function (e) {
      if (e && e.preventDefault) e.preventDefault();
      const product = ATYAB_byId ? ATYAB_byId(id) : null;
      if (!product) return;
      const money = makeMoney(language, currency);
      const url = shareUrlOf(id);
      const title = (product.kindLabel ? "بخور " : "عطر ") + product.name + " — أطياب الجاسم";
      const text = "شاهد " + product.name + " بسعر " + money.format(product.price);

      if (navigator.share) {
        navigator.share({ title: title, text: text, url: url }).catch(function () {
          /* أُلغيت المشاركة — لا رسالة */
        });
        return;
      }
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(url).then(
          function () {
            dispatch(uiActions.toastShown("تم نسخ رابط " + (product.kindLabel ? "البخور" : "العطر")));
          },
          function () {
            dispatch(uiActions.toastShown(url));
          }
        );
        return;
      }
      dispatch(uiActions.toastShown(url));
    },
    [dispatch, id, language, currency]
  );

  if (props.variant === "tool") {
    return (
      <button className="pd-tool pd-share" type="button" data-share={id} onClick={onShare}>
        <Icon name="share" strokeWidth={1.8} />
        <span>
          <b>شارك</b>
          أرسل الرابط لصديق
        </span>
      </button>
    );
  }

  if (props.variant === "mini") {
    /* ★ R17: أيقونة فوق صورة المنتج (هاتف) — بدل الزر العريض */
    return (
      <button className="pd-mini" type="button" data-share={id} aria-label="مشاركة المنتج" title="مشاركة المنتج" onClick={onShare}>
        <Icon name="share" strokeWidth={1.8} />
      </button>
    );
  }

  return (
    <button className={props.className || "btn-ghost"} type="button" onClick={onShare}>
      <Icon name="share" strokeWidth={1.8} />
      <span>{props.children || "شارك المنتج"}</span>
    </button>
  );
}
