/* ============================================================
   أطياب الجاسم (React) — صفحة عرض تفاصيل المنتج (ShowProductDetailsPage)

   غرضها: استدعاء ProductDetails (الذي يجلب المنتج بنفسه من Redux عبر
   الـid) ثم UserRate الخاص بالمنتج نفسه.

   ★ من يأتي بالـid؟ الراوتر: المسار /product/:id → useParams().id
     (وتصل إليه من بطاقة المنتج أو من زر «تفاصيل المنتج» في
     ProductButtons/العروض).
   ============================================================ */

import { useParams } from "react-router-dom";
import { useEffect } from "react";
import { usePageMeta } from "../usePageMeta.js";
import { useAppDispatch, useAppSelector } from "../redux/hooks.js";
import { getAllPerfumes } from "../redux/slices/perfumesSlice.js";
import { getAllOuds } from "../redux/slices/oudsSlice.js";
import { getAllIncenses } from "../redux/slices/incensesSlice.js";
/* ★ R23: تفاصيل الأصناف الجديد عند الدخول المباشر */
import { getAllMists } from "../redux/slices/mistsSlice.js";
import { getAllLotions } from "../redux/slices/lotionsSlice.js";
import { getAllMukhamaria } from "../redux/slices/mukhamariaSlice.js";
import { getAllHair } from "../redux/slices/hairSlice.js";
import { getProductImages } from "../redux/slices/imagesSlice.js";
import { getProductProfile } from "../redux/slices/productProfilesSlice.js";
import { refreshCatalogStock } from "../redux/catalogStock.js";
import { atyabLog } from "../redux/api.js";
import { productName, tr2 } from "../i18n.js";
import ProductDetails from "../components/Product/ProductDetails.jsx";
import UserRate from "../components/UserExperience/UserRate.jsx";
import { rateKeyFor } from "../redux/slices/reviewsSlice.js";
import { ATYAB_byId } from "../data/products.js";

export default function ShowProductDetailsPage() {
  const params = useParams();
  const id = Number(params.id) || 0;
  const dispatch = useAppDispatch();

  /* ★ المنتجات من Redux — تُجلب من الـ API عند الدخول المباشر والقوائم فارغة
     (كل thunk فيه condition يمنع التكرار، فيُنفَّذ الناقص فقط).
     ★ التأثير يعمل مرة واحدة لكل منتج [dispatch, id] — لا counts حتى لا يتكرر التركيب مع وصول القوائم */
  useEffect(
    function () {
      atyabLog("page product:mount", id);
      dispatch(getAllPerfumes());
      dispatch(getAllOuds());
      dispatch(getAllIncenses());
      dispatch(getAllMists());
      dispatch(getAllLotions());
      dispatch(getAllMukhamaria());
      dispatch(getAllHair());
      /* ★ v17-S1: مخزون خفيف عند كل دخول (dedupe للمتزامن فقط) —
         من عاد للعطر يرى الكمية الطازجة */
      refreshCatalogStock(dispatch);
      /* ★ v17-S1: البروفايل force عند كل زيارة للمنتج (dedupe للمتزامن
         فقط، والفشل لا يصبح كاشاً)؛ المعرض يُجلب كالمعتاد */
      if (id > 0) { dispatch(getProductProfile({ id: id, force: true })); dispatch(getProductImages(id)); }
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [dispatch, id]
  );

  const product = ATYAB_byId ? ATYAB_byId(id) : null;
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });

  usePageMeta({
    route: "product",
    catalog: product && product.kind === "oud" ? "ouds" : product && product.kind === "incense" ? "incense" : product && (product.kind === "mists" || product.kind === "lotions" || product.kind === "mukhamaria" || product.kind === "hair") ? product.kind : "perfumes",
    titleAr: product ? product.name : "منتج",
    titleEn: product ? productName(product, "en") : "Product"
  });

  return (
    <section className="container view pd" id="productView">
      <ProductDetails id={id} />
      {product ? (
        <section className="reviews" id="reviewsSection">
          <div className="reviews-head">
            <span className="eyebrow">آراء العملاء</span>
            <h2>{tr2(language, "Reviews of " + productName(product, "en"), "تقييمات «" + product.name + "»")}</h2>
            <p className="reviews-sub">آراء المشترين حول هذا المنتج، ويمكنك إضافة تقييمك في الأسفل.</p>
          </div>
          <div className="reviews-box">
            <UserRate
              channelKey={rateKeyFor(product.id)}
              product={product}
              noun={product.kindLabel ? "بخور" : "عطر"}
              formTitle={tr2(language, "Your opinion matters", "رأيك يهمنا")}
            />
          </div>
        </section>
      ) : null}
    </section>
  );
}
